import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { getTheme, STATUS_COLORS } from '../utils/theme';
import { Icons } from '../utils/icons';
import SearchBar from '../components/common/SearchBar';
import Badge from '../components/common/Badge';

const TABS = [
  { key: 'note',  label: 'Notes', icon: <Icons.Book /> },
  { key: 'paper', label: 'Papers', icon: <Icons.FileText /> },
  { key: 'video', label: 'Videos', icon: <Icons.Video /> },
  { key: 'doubt', label: 'Doubt Sessions', icon: <Icons.MessageCircle /> },
];

export default function Resources() {
  const { selectedCollege, resources, dark, toast, user } = useApp();
  const css = getTheme(dark);
  const [tab, setTab] = useState('note');
  const [search, setSearch] = useState('');
  const [subject, setSubject] = useState('all');

  const displayCollege =
    user?.role === 'student' && user?.college
      ? user.college
      : selectedCollege;

  const subjects = ['all', ...new Set(resources.map((r) => r.subject))];

  const filtered = resources.filter((r) => {
    const matchType = r.type === tab;
    const matchSearch =
      r.title.toLowerCase().includes(search.toLowerCase()) ||
      r.subject.toLowerCase().includes(search.toLowerCase());
    const matchSubject = subject === 'all' || r.subject === subject;

    // ✅ FIXED HERE
    const matchCollege =
      user?.role === 'student'
        ? true
        : (
            !selectedCollege ||
            r.college === selectedCollege?._id ||
            r.college?._id === selectedCollege?._id
          );

    return matchType && matchCollege && matchSearch && matchSubject;
  });

  return (
    <div className="fade-in">
      <h1>{displayCollege ? displayCollege.short : 'All'} Resources</h1>

      <div>
        {filtered.map((r) => (
          <div key={r._id}>
            <h3>{r.title}</h3>

            {/* ✅ SAFE RENDER */}
            <p>
              {r.subject} · {r.uploadedBy?.name || r.uploadedBy}
            </p>

            {/* ✅ SAFE COLLEGE */}
            <p>
              {r.college?.name || r.college}
            </p>
          </div>
        ))}
      </div>
    </div>
  );
}
